{
  "premises": [
    {
      "statement": "Every retained year-quarter has at least one hire and at least one application in each demographic group used as a hire-rate denominator.",
      "about": "data",
      "target": "greenhouse__diversity_metrics",
      "evidence_of_dependence": "female_hires * 100.0 / NULLIF(female_applications, 0) AS female_hire_rate; veteran_hires * 100.0 / NULLIF(total_hires, 0) AS veteran_hire_representation",
      "alternative": "The contract requires percentages to \"return 0 when the denominator is 0\"; these expressions instead return NULL, and the final SELECT does not default the rate columns to zero.",
      "importance": 4,
      "reason": "Any absent demographic group or quarter without hires produces null percentages instead of the required zeros.",
      "updates": null
    },
    {
      "statement": "Process duration in days means elapsed timestamp time divided by 24 hours, including fractional days, rather than the number of calendar-day boundaries crossed.",
      "about": "requirement",
      "target": "greenhouse__recruitment_performance.avg_process_days; greenhouse__talent_pipeline_simplified.avg_process_days",
      "evidence_of_dependence": "AVG(DATE_DIFF('microsecond', a.applied_at, COALESCE(a.rejected_at, a.last_activity_at)) / 86400000000.0) AS avg_process_days",
      "alternative": "Both contracts describe \"average days from applied_at\" and require no rounding, but do not explicitly distinguish elapsed fractional days from calendar-day differences.",
      "importance": 2,
      "reason": "The interpretation changes process-duration averages and can change the recruitment model's 30-day fast-process flag.",
      "updates": null
    }
  ],
  "fewer": [
    {
      "target": "greenhouse__diversity_metrics",
      "count": 1,
      "reason": "The remaining visible joins, grouping, exact-match demographic conditions, thresholds, and ordering are explicitly specified; no additional unestablished premises were identified."
    },
    {
      "target": "greenhouse__recruitment_performance",
      "count": 1,
      "reason": "Apart from the duration interpretation, the contract explicitly supports the joins, non-distinct completed-interview count, score mapping, rate defaults, tiers, and flags."
    },
    {
      "target": "greenhouse__talent_pipeline_simplified",
      "count": 1,
      "reason": "Apart from the duration interpretation, the source enrichment, interview existence test, aggregation, rate defaults, rankings, and tiers follow explicit contract instructions."
    }
  ]
}
